CREATE TABLE IF NOT EXISTS c_accountexports (_id TEXT PRIMARY KEY NOT NULL, accountId TEXT, data TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS i_accountexports__accountId ON c_accountexports (accountId);
CREATE INDEX IF NOT EXISTS i_accountexports__accountId__createdAt_d ON c_accountexports (accountId ASC, json_extract(data, '$.createdAt') DESC);
CREATE INDEX IF NOT EXISTS i_accountexports__status__expiresAt ON c_accountexports (json_extract(data, '$.status') ASC, json_extract(data, '$.expiresAt') ASC);
CREATE INDEX IF NOT EXISTS i_contacts__newsletterId__referral_count_d___id ON c_contacts (json_extract(data, '$.newsletterId') ASC, json_extract(data, '$.referral.count') DESC, _id ASC) WHERE json_type(data, '$.referral.count') IS NOT NULL;
CREATE TABLE IF NOT EXISTS c_exportfiles (_id TEXT PRIMARY KEY NOT NULL, accountId TEXT, data TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS i_exportfiles__accountId ON c_exportfiles (accountId);
CREATE UNIQUE INDEX IF NOT EXISTS u_exportfiles__exportId__path ON c_exportfiles (json_extract(data, '$.exportId') ASC, json_extract(data, '$.path') ASC);
CREATE INDEX IF NOT EXISTS i_exportfiles__exportId__order ON c_exportfiles (json_extract(data, '$.exportId') ASC, json_extract(data, '$.order') ASC);
CREATE INDEX IF NOT EXISTS i_exportfiles__exportId__state ON c_exportfiles (json_extract(data, '$.exportId') ASC, json_extract(data, '$.state') ASC);
CREATE TABLE IF NOT EXISTS c_referrals (_id TEXT PRIMARY KEY NOT NULL, accountId TEXT, data TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS i_referrals__accountId ON c_referrals (accountId);
CREATE UNIQUE INDEX IF NOT EXISTS u_referrals__referredId ON c_referrals (json_extract(data, '$.referredId') ASC);
CREATE INDEX IF NOT EXISTS i_referrals__referrerId__status ON c_referrals (json_extract(data, '$.referrerId') ASC, json_extract(data, '$.status') ASC);
CREATE INDEX IF NOT EXISTS i_referrals__newsletterId__status__createdAt_d ON c_referrals (json_extract(data, '$.newsletterId') ASC, json_extract(data, '$.status') ASC, json_extract(data, '$.createdAt') DESC);
CREATE INDEX IF NOT EXISTS i_referrals__newsletterId__createdAt_d___id_d ON c_referrals (json_extract(data, '$.newsletterId') ASC, json_extract(data, '$.createdAt') DESC, _id DESC);
CREATE TABLE IF NOT EXISTS c_referralrewards (_id TEXT PRIMARY KEY NOT NULL, accountId TEXT, data TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS i_referralrewards__accountId ON c_referralrewards (accountId);
CREATE UNIQUE INDEX IF NOT EXISTS u_referralrewards__contactId__rewardId ON c_referralrewards (json_extract(data, '$.contactId') ASC, json_extract(data, '$.rewardId') ASC);
CREATE INDEX IF NOT EXISTS i_referralrewards__newsletterId__createdAt_d ON c_referralrewards (json_extract(data, '$.newsletterId') ASC, json_extract(data, '$.createdAt') DESC);
